import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSikhData(){const e=readFileSync(resolve(__dirname,"../../sikh-empire-coinage-explorer/sikh-coin-data.js"),"utf-8");return new Function(e+"\nreturn { SIKH_INFO, COIN_EXAMPLES, INSCRIPTION_BREAKDOWN, SIKH_MINTS, TIMELINE_EVENTS, REFERENCES };")()}describe("Sikh Empire Coinage Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadSikhData()}),describe("SIKH_INFO metadata",()=>{it("contains correct Sikh Empire coinage metadata and sacred motto",()=>{expect(e.SIKH_INFO.id).toBe("sikh-empire-coinage"),expect(e.SIKH_INFO.title).toContain("Sikh Empire"),expect(e.SIKH_INFO.ruler).toContain("Ranjit Singh"),expect(e.SIKH_INFO.sacredMotto).toContain("Deg Tegh Fateh")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SIKH_INFO.quickStats)).toBe(!0),expect(e.SIKH_INFO.quickStats.length).toBe(6)})}),describe("COIN_EXAMPLES & INSCRIPTION_BREAKDOWN",()=>{it("contains representative Nanakshahi coins and inscription decoder entries",()=>{expect(Array.isArray(e.COIN_EXAMPLES)).toBe(!0),expect(e.COIN_EXAMPLES.length).toBeGreaterThanOrEqual(4);const t=e.COIN_EXAMPLES.find(e=>"lahore-nanakshahi-rupee"===e.id);expect(t).toBeDefined(),expect(t.metal).toContain("Silver"),expect(Array.isArray(e.INSCRIPTION_BREAKDOWN)).toBe(!0),expect(e.INSCRIPTION_BREAKDOWN.length).toBeGreaterThanOrEqual(4)})}),describe("SIKH_MINTS & REFERENCES",()=>{it("contains imperial mints and reference works",()=>{expect(Array.isArray(e.SIKH_MINTS)).toBe(!0),expect(e.SIKH_MINTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});